    "description": "元素（气，地，火，水和木）。本法术有五个不同的法术，每一版本都必须单独学习。每一元素版本的法术都能让角色更好地对抗突然和长时间的特定元素暴露。魔法师将元素召到他的掌心上并进行一次施法检定对抗目标的秘法防御。如果成功，当他接触目标时，手上的元素就会消失。目标对抗基于该元素的伤害时获得+3的物理和秘法护甲。\n本法术的不同元素版本可以被保存在同一个法术矩阵中。",
