    "description": "木元素。束缚。本法术可以召唤一个木元素并将其暂时束缚在一个自愿目标身上。魔法师将一只手覆在树上，另一种覆于目标的额头上。进行一次施法检定对抗目标的秘法防御。如果成功，目标的血管和眼睛将变成绿色，他能够聆听并理解自然区域内木元素与精魂的缓慢对话。\n在法术持续期间的任何时刻，被束缚了元素的角色都可以宣言他们正在寻找一个活着的生物。在此宣言后，木精魂会积极地开始协助寻找，任何适用的检定都会获得+5。此外，角色的移动速率增加4。\n一旦被束缚的角色开始狩猎，任何来自该狩猎的干扰都会导致法术立刻终止。倘若本法术因为任何原因提前结束，目标的感官会被削弱，所有行动检定承受-3，直至他获得一整晚的休息，并且这个法术在一整天内无法再次施放。此法术同一时间只能施放激活一次。",
    "nameCn": "林地猎手的斗篷",
    "weavingBase": 6,
    "weavingHigh": 11,
    "castingType": "TMD",
    "castingDn": null,
    "aoe": "",
    "armorType": "none",
    "desc": "木元素。束缚。本法术可以召唤一个木元素并将其暂时束缚在一个自愿目标身上。魔法师将一只手覆在树上，另一种覆于目标的额头上。进行一次施法检定对抗目标的秘法防御。如果成功，目标的血管和眼睛将变成绿色，他能够聆听并理解自然区域内木元素与精魂的缓慢对话。\n在法术持续期间的任何时刻，被束缚了元素的角色都可以宣言他们正在寻找一个活着的生物。在此宣言后，木精魂会积极地开始协助寻找，任何适用的检定都会获得+5。此外，角色的移动速率增加4。\n一旦被束缚的角色开始狩猎，任何来自该狩猎的干扰都会导致法术立刻终止。倘若本法术因为任何原因提前结束，目标的感官会被削弱，所有行动检定承受-3，直至他获得一整晚的休息，并且这个法术在一整天内无法再次施放。此法术同一时间只能施放激活一次。"
