    "description": "水元素。束缚。本法术可以召唤一个水元素并将其暂时束缚在一个自愿目标身上。魔法师凝视目标的双眼（或一面镜子）并安慰性地抚摸它们，进行一次施法检定对抗目标的秘法防御。如果成功，目标的眼睛会在强烈情绪暂时离开他们时变得平静而富有诱惑力。\n束缚角色能在交谈中引起他人注意，并采取一种恭维赞美的态度与举止，从而在其交谈（Conversation）检定中获得+4。每获得一成功都能让他们针对目标的态度和感受提出一个笼统的问题。角色可以通过这种方式进行多次交谈检定，但每次后续检定的难度都会+5。后续检定可收集到更具体的信息，但必须与交谈直接相关（由GM判定），如果角色在交谈检定中失败，法术立刻终止。\n如果束缚角色表达了目标之前没有表达出的任何强烈意见或情绪、强行操控的互动或是对目标施压，法术会立即终止。若法术因任何原因提前结束，束缚角色将在所有基于魅力的检定中承受-5的罚值，直到他获得一整晚的休息，并且这个法术在一整天内无法再次施放。此法术同一时间只能施放激活一次。",
    "nameCn": "倒映水面的斗篷",
