    "description": "木元素。本法术可以将任何种类的植物材料转化成一顿美味盛宴。本法术需要三株完整植物，不论它们有多干瘦。\n魔法师将植物切成或撕成小块，然后进行一次施法检定（6）。如果成功，其效果检定决定了制作出的餐食的数量。餐点包括以下部分：开胃菜、汤、沙拉、面包、主菜、蔬菜与甜点，每一餐都一模一样。虽然它们看起来像有肉，但实际上并没有。这些餐食与它们的真品一样营养美味。\n本法术只会制造出魔法师在过去一年零一天内吃过的食物种类，这给了他一个偶尔吃太多好东西的理由。没吃完的餐点会在法术结束时消失。",
