    "description": "地元素。本法术可以从一把泥土、一块石头或直接从大地中制造出一根长杖。魔法师触碰材料进行一次施法检定。如果成功，一根五英尺长的杖（具有所有相同的属性）就会被塑造成形，可在战斗中用作近战武器。每一根地元素杖的外观因元素师而各异，并且会随着他环数的增加而变化（通常会变得更独特更华丽）。持握有地元素杖时，所有成功施放的元素术法术都被视作具有一额外成功。只有具有元素术知识的人才能使用地元素杖，如果一名没有元素术知识的角色在战斗中持用了地元素杖，法术会在杖被使用后立即结束，不会产生任何效果并将恢复层它原本的组分。",
