    "description": "地元素。本法术用血魔法提高了土地种植粮食的速度。魔法师用一件锋利的物品刺破他的手让一滴血落在地上，承受1点血魔法伤害（此伤害可在法术结束后被治愈），进行一次施法检定对抗土地的秘法防御（一般为6）。如果成功，半径100码内的土壤将因魔法变得丰腴，这片土地在一年零一天之内异常肥沃。植物在这种土壤中的生长速度大约是正常生长速度的两倍，由GM决定这种生长的具体效果。\n许多地下卫城通过使用本法术得以活过天灾，它使得许多重建在容易遭受恶劣天气影响地区的城镇能够在地表繁荣兴盛。有传闻说托罗斯科（Trosk）镇的贾斯普利的探求者正在试图通过打量使用这条法术来治愈荒劣之地。",
