    "description": "气元素-电。本法术可以将魔法师传送至范围内他可见的任何地方。魔法师的当前位置与目的地都必须开阔可见天空。\n魔法师用一只手指向他的目的地，然后用另一只手指向天空，进行一次施法检定对抗他自己的秘法防御。如果成功，闪电会同时击中他和目的地，在两处地面上留下魔法师特有的印记。魔法师立即被传送至目的地，如果魔法师获得一成功，他会迷失方向并在下一轮无法行动。获得两成功则能够在下一轮中如常行动。如果魔法师获得三成功，他就像在本轮未采取任何行动一样能够立即行动。如果施法检定失败，魔法师会被闪电击中，承受意志+6/物理伤害。在同一日内每多用一次此法术就会累加+5的施法难度调整。",
