    "description": "火元素。束缚。本法术可以召唤一个火元素并将其暂时束缚在一个自愿目标身上。魔法师向目标洒下火花，然后触碰目标并进行一次施法检定对抗目标的秘法防御。如果成功，目标的将会愤怒地咆哮，同时被火焰吞噬。任何在近战中与目标交战者都会自动承受效果检定的伤害量（物理护甲可用）。\n目标的伤害检定得到等同于效果Step的火焰伤害奖励骰。\n目标每一轮都必须使用猛烈攻击选项（即便通常情况下不适用，如使用远程武器），但这不会导致劳累值（Strain）。目标必须进行攻击或以其全力移动速度向他们下一名对手处移动并一心要攻击那名对手。如果不能做到以上任何一点，火元素就会强行离开目标，导致对目标的效果Step+2的伤害量（任何护甲都不可用）。\n任何试图欺骗元素而不与对手交战的行为都会导致法术立即提前终止。此法术同一时间只能施放激活一次，并且与火焰武器和火焰编织不兼容。魔法师可以选择在施放法术时降低其效果Step。",
