    "description": "水元素-酸。本法术会导致酸雨从天空中落下。法术需要云层，可以是自然产生的也可以是唤云术（288页）之类魔法的产物。魔法师需要说出友方的真名，然后将其施法检定结果与效果区域之内所有没有被唤出真名的目标的秘法防御相比较。如果成功，腐蚀性的雨水就会从云层落到目标身上。\n接触到酸雨的每轮都会对目标造成Step 8/2D6的伤害。魔法师和那些施法时被唤出真名的人不受影响。若魔法师选择专注（concentrate），酸雨的强度将会提高，魔法师将其意志Step加入到每轮酸雨造成的伤害检定中。一旦他的专注被打破，魔法师就不能再次进入专注，除非他重新施放法术。即便魔法师失去了专注，法术也将持续下去，直至它结束。如果魔法师发生移动，效果区域亦不会变化。",
