    "description": "木元素。束缚。本法术可以召唤一个木元素并将其暂时束缚在一个自愿目标身上。魔法师用一根棘刺刺伤目标，进行一次施法检定对抗目标的秘法防御。如果成功，荆棘会从目标的血肉之中生出并使其立刻承受1负伤。不过，目标在法术持续期间免疫负伤罚值。因此，很多惧魔都会在这段时间里无视掉他们。\n目标可以承受最大等于其意志Step的劳累值（Strain）来从10码的范围内抽生出数量等同于承受劳累值的2码×2码的荆棘。这些荆棘以目标的血为食，将迅速从地面生长出来，渴求更多血的滋养。除了被束缚的角色以外的任何角色接触到荆棘都会承受Step4的伤害值，且任何护甲都不可用于抵抗这种伤害。",
