    "description": "气元素-电。束缚。本法术需要云层，可以召唤一个气元素并将其暂时束缚在一个自愿目标身上。魔法师将一只手伸向天空，另一只手触摸目标，进行一次施法检定对抗目标的秘法防御。如果成功，闪电将击中他举起的手并向目标移动，最终在电流通过目标身体时从地面举起他。目标获得16的飞行移动速率并且可以通过专注使其周身2码半径的区域里环绕起电流，使该区域内任何自愿目标浮空并与他一起移动。\n这样做的时候，束缚目标只能移动和进行自由动作（Free Actions）。\n在法术持续期间的任何时刻，被束缚了元素的角色都可以宣言他们正在寻找一个活着的生物。在此宣言后，木精魂会积极地开始协助寻找，任何适用的检定都会获得+5。此外，角色的移动速率增加4。\n束缚目标获得+2的先攻检定加值。目标的出现总是有预兆的，无法进行措手不及和惊愕攻击。\n如果目标因为任何原因触碰到地面，法术会立刻结束。\n如果法术因为任何原因提前结束，目标会承受1负伤，并且这个法术在一整天内无法再次施放。此法术同一时间只能施放激活一次。",
    "nameCn": "闪电先锋的斗篷",
