    "description": "幻象。本法术可以伪装起一个人的身份。魔法师将水或者古龙水泼在目标的脸上，进行一次施法检定对面目标的秘法防御。如果成功，目标的面目将会改变成魔法师所想的样子——若他试图模仿一张特定的容貌，他必须在最近一个月内见过那个人。\n当目标试图说服他人相信他的假身份并根据错觉行动时，目标在伪装自身Disguise Self（若他们没有伪装自身则可将其作为默认技能）或基于魅力的检定中获得+3加值。对目标进行的任何互动检定都被视作看破检定Sensing tests（见266页幻象）。本法术只会影响到目标的头部和颈部，包括头发和耳朵。目标面部和被模仿的对象面部之间最大的尺寸差异为各维的100%，魔法师必须找到别的方法去掩盖明显差异。目标的声音不会发生变化，所以他必须尽量去模仿被借用了脸的那个人的说话特征。",
    "nameCn": "易容术",
    "weavingBase": 5,
    "weavingHigh": 10,
