    "description": "虚像。本法术可以制造出一场普通视线无法看到的地方发生的灾难的虚像。魔法师漫不经心地环顾四周，然后停下来盯着地平线上的一固定点，大声说出\"哦，激情在上，瞧瞧那边！\"或者\"那到底是啥？\"之类的话，进行一次施法检定对抗目标群体中最高的秘法防御，每多一名额外目标就会让难度+1。如果成功，魔法师选定的灾难的证据就会被法术制造出来：一缕烟从村庄屋顶升起，人们尖叫的声音或是其他小但会导致分心的虚像。\n目标的注意力会被引到灾难的假象上，被分心到足够对他进行等同于措手不及的攻击。魔法师可以影响至多等同于其施法等级数的目标。法术不能在小的封闭环境中施放，比如没有窗户的房间。如果被用于战斗中的目标或被卷入其他类似活动的目标，魔法师必须得到一额外成功才能让法术对目标生效。所有被法术影响到的人在被行动检定（如攻击检定）作为目标时会被吸引走注意力并不再受法术影响。若本法术此前已经影响到了一名目标，而该目标因此受到攻击，则本法术必须等到第二天才能再次施放于该目标身上。",
    "nameCn": "灾难虚景",
    "weavingBase": 5,
    "weavingHigh": 10,
    "castingType": "TMD",
    "castingDn": null,
    "aoe": "",
    "armorType": "none",
