    "description": "幻象。本法术通过让旁观者相信他们变成了怪物来提升角色的战斗能力。\n魔法师发出咆哮声，接着触碰目标，进行一次施法检定对抗目标的秘法防御。如果成功，双螺旋的光芒会出现在目标周身不断旋转，最终形成一个巨大的人形生物，人形生物往往在体型上更为巨大，并会获得超自然的特征，比如手上长出斧刃、触手或巨大的钳子。\n目标在其近战攻击和伤害检定与物理防御中获得+2加值。幻象不会给予目标任何特殊攻击形式和能力。所有与目标互动的物理检定都被视作看破检定，比如攻击检定、回避打击检定和反击（Riposte）检定。",
