    "description": "幻象。本法术可以隐藏起角色。魔法师专注地想着\"这里没有人\"并进行一次施法检定对抗效果区域内所有角色（包括其自身）最高秘法防御。如果成功，被影响的人在效果区域之外的人看来就会隐形。一旦被施放，法术的效果就不会再随着魔法师的移动而移动，只有原本的目标会得到法术隐形的好处，后来进入区域的目标不受影响。离开效果区域的目标于其他人而言会变得可见，他们可以通过回到圆环内重新获得隐形。\n一名角色走进幻象区域时需要进行一次视作看破检定的感知检定（见266页幻象）。如果隐藏起的目标要用一种能解释的方式操纵环境（如移动在视线范围内的书籍、开关门等），观察方会在其感知检定中获得+3加值。若隐藏起的目标和观察方有物理接触，后者在感知检定中获得+5加值。若成功，观察方便会看破幻象。\n若失败，观察方的感官反馈会被魔法所抑制，他的感官能够侦测到一般情况下可见的角色，但其知识却被法术给抑制。如果一个隐藏起的目标对另一名角色造成伤害，被攻击者将不再受幻象影响，任何旁观者需立即进行一次+5的看破检定。",
