    "description": "幻象。本法术会形成角色的三个幻影，令他在战斗中更难被击中。魔法师以一种缓慢而抽象的方式移动双手，然后指向目标，进行一次施法检定对抗目标的秘法防御。如果成功，三个与目标相同的图像就会出现，它们始终保持在目标1码之内的地方，偶尔会在移动时与其重叠。图像不会与目标完全同步移动，在目标采取防御姿态时，一个图像可能会高举手中的剑，另一个则将剑放低，同时第三个的剑刃在进行刺击。图像会迷惑对手，法术持续期间，目标每有一幻象（+3）就能在其物理防御中获得+1加值。目标采取的攻击对对手而言更难回避和防御——每有一幻象（-3）就会让他们在应对目标攻击的回避打击、反击或其他防御性行动检定中承受-1罚值。这些检定被视作看破检定。\n四环",
