    "description": "虚像。本法术会制造出一个想象的声音去说服其他人行使魔法师的意志。魔法师轻轻自语，进行一次施法检定对抗目标群体中最高的秘法防御，每多一名角色难度+1。\n如果成功，一个相当有魄力的幻象之音便会将魔法师的话语翻译成每个目标相应的语言。目标接下来会遵照声音的指示行动，只要这样的行动不会对他人造成明显伤害。魔法师获得三成功的情况下，目标会被愚弄去采取被建议的行动，即便这样做会伤害到其他人。\n若目标被说服去遵循会伤害他人的行动指示或以某种方式违背了目标的意愿，目标可以在执行命令之前进行一次意志检定对抗效果Step。魔法师能够影响至多等同于其施法等级数的目标，目标不会伤害自己，这么做的建议将立即终止法术对他的效果。",
