    "description": "幻象。本法术可以将两个小容器（比如帽子和小罐）刚好能让人把手伸进去的开口连接起来，这两个容器相距不能超过10码。魔法师必须持有其中一个容器，另一只容器则必须在他可见范围内。魔法师在一只容器上挥舞他的手念诵魔法咒文，然后进行一次施法检定（6）。如果成功，魔法师就可以通过他持有的容器开口摸到另一个容器内，他的手会从远处的容器开口处伸出伸入。魔法师能够将任何可以通过开口的物体拉回。两个开口由扭曲的星界空间连接。这样的扭曲真实存在，但法术会依靠折曲魔法的幻术前提来抄很多近道，这种幻术能被破坏并导致连接失效。一次成功的看破检定会破坏掉连接并终止法术。",
