    "description": "本法术会让其他人面对方向的选择时遵循魔法师选定的路线行动。魔法师指定一条可见路径（一组门，分岔道的其中一条等），然后宣言其选择，进行一次施法检定（6）。如果成功，在其他人于同一地点面临方向选择时，目标群体会相信他们已经做出了选择，但他们实际上选取的是魔法师预先选定的路径。一旦他们脱离法术范围或法术结束，这样的欺骗就会变得很明显。如果目标群体决定返程并从同一点选择正确的路径，他们需要进行一次意志检定对抗效果Step来决定他们是否会再次被转向错误路径上。",
