    "keywords": [],
    "description": "本法术会将一块地毯或其他不超过四平方码的布料变成一个飞行平台。魔法师大力抖动毯子或布料，进行一次施法检定（7）。如果成功，材料会活化并浮动在离地几英寸的地方。它的基本承重能力为200磅。飞毯的物理防御和秘法防御与施法者的相同，如果飞毯受到了大于等于其死亡等级（30）的伤害，法术就会结束。\n魔法师可以用言语控制飞毯，这需要他的专注。他可以将飞毯的指挥权交给另一角色，后者能够以同样的方式用言语控制它。魔法师可以通过一次成功的施法检定（7）重获飞毯的指挥权。飞毯没有智力，很容易陷入迷惑，所以对它发出的必须是简单的指令，最好限制在几个词的长度。飞毯通常会以16的移动速率在地面之上几英寸的地方飞行，但如果被下了相应的指令，它也可以飞到100码高的地方，每水平移动2码就会在同时垂直上升2码。魔法师可以通过承受2点血魔法伤害来将法术持续延时到一年零一天。该伤害无法被治愈，直到飞毯被破坏或法术结束。",
    "nameCn": "飞毯术",
    "weavingBase": 10,
    "weavingHigh": 15,
    "castingType": "fixed",
    "castingDn": 7,
