    "description": "幻象。本法术会召唤出一条由墨黑阴影组成的恶龙的幻象。\n魔法师用他的手在墙壁或其他表面做出一条龙的头部的暗影图像，进行一次施法检定（12）。如果成功，一条6码高10码长4码宽的龙就会从施法区域内的影子中融合而成。每一轮，魔法师可以通过专注来指定一个在龙旁边的目标，唤出的影龙会使用魔法师的施法Step进行攻击。如果成功，魔法师就可以用效果Step进行伤害检定。龙的移动速率为16，如果有足够空间的话它便飞过障碍物。任何与龙互动的检定（如攻击检定、回避打击）都被视作看破检定。",
    "nameCn": "龙腾术",
    "weavingBase": 11,
    "weavingHigh": 16,
    "castingType": "fixed",
    "castingDn": 12,
    "aoe": "",
    "armorType": "pa",
    "desc": "幻象。本法术会召唤出一条由墨黑阴影组成的恶龙的幻象。\n魔法师用他的手在墙壁或其他表面做出一条龙的头部的暗影图像，进行一次施法检定（12）。如果成功，一条6码高10码长4码宽的龙就会从施法区域内的影子中融合而成。每一轮，魔法师可以通过专注来指定一个在龙旁边的目标，唤出的影龙会使用魔法师的施法Step进行攻击。如果成功，魔法师就可以用效果Step进行伤害检定。龙的移动速率为16，如果有足够空间的话它便飞过障碍物。任何与龙互动的检定（如攻击检定、回避打击）都被视作看破检定。"
