    "description": "本法术会静默一群角色或动物发出的声音，包括他们移动、说话、呼吸的声音和马的嘶鸣等等。魔法师在这群目标之间四处游荡，触碰所有被法术影响的人和动物，然后进行一次施法检定对抗目标群体最高的秘法防御，每多一名角色难度+1。如果成功，目标群体发出的任何声音都会被压制——所有人在基于隐秘（stealth）的行动检定中获得+4加值。即便之前没有，目标也可以使用隐秘步伐作为默认技能。用于侦测目标群体中任何角色而进行的基于听觉的感知检定的侦测难度+4。魔法师可以影响最多等同于其施法等级数×3的目标。法术无法在基于视觉、嗅觉或触觉的感知检定中藏匿目标。",
