    "description": "本法术会制造出一道通过墙壁、门户或其他不超过2码厚的障碍物的临时通道。魔法师进行一次施法检定对抗障碍物的秘法防御。如果成功，他就会制造出一个开口，但它不算特别稳定，会随机地翻滚扭动、收缩扩张。成功数决定了与人类相比开口的大小。\n一个成功的情况下，开口每轮可以挤过一名角色，这会需要一次成功的敏捷检定（7）。两个成功时，每轮可以让一名角色轻松通过（无需敏捷检定）。三成功则每轮能让等同于魔法师施法等级数的目标轻松通过开口。\n八环",
