    "description": "幻象。本法术会连接起两个相距不超过一英里的入口。法术必须在两小时之内施放两次，第一次于目的地的传送门施放，第二次在出发点的门施放。\n魔法师分别对两扇门进行施法检定对抗各自的秘法防御。如果两次检定都成功，通过出发门的角色就会立即穿过两扇门之间的距离从出口门出来。这两扇门由扭曲的星界空间连接。这样的扭曲真实存在，但法术会依靠折曲魔法的幻术前提来抄很多近道，这种幻术能被破坏并导致连接失效。一次成功的看破检定会破坏掉连接并终止法术。",
