    "description": "此法术可以命令一只夜间活动的、能飞行的生物去传递信息。\n这个法术必须在日落后施放，并且只能在魔法师通过动物伙伴（animal companion）或使用命令夜行者（Command Nightflyer）天赋（135页）已经控制住的夜行者身上施放。要传递是信息必须很简洁，单词数不能超过施法者施法等级的两倍。\n魔法师抚摸夜行者并向其耳语他要传递的信息，说出接收者的名字，然后进行一次施法检定对抗生物的秘法防御。\n如果成功，它就会飞起来并准确无误地找到指定收件者，接着用魔法师自己的声音低声传递讯息。如果夜行者不能在法术结束或日出之前（不论二者谁先到）抵达收件者身边，讯息便会丢失。",
