    "description": "本法术可以让魔法师目睹并体验一名角色的死亡瞬间。通过这样的行为，魔法师会触碰到精魂世界并重现导致角色死亡的事件。魔法师闭上双眼，然后将手掌指向尸体，进行一次施法检定对抗目标的秘法防御（同其生前数据）。如果成功，目标生命中最后的几轮一直到目标死亡内的景象就会被展现给魔法师。\n魔法师必须进入出神（trance）状态来专注于维持法术。在这种状态下，他会从死者的视角感知到一切。不幸的是，这也会让魔法师承受死者死前受到的所有伤害。\n效果检定会给魔法师带来临时伤害点数（temporary Damage Points）。魔法师受到的任何伤害都会先削减其临时伤害点数，然后再加到他的当前伤害上（秘法护甲可用）。魔法师无法从本法术产生的效果中承受负伤。但是，如果他的当前伤害等于或超过了他的意识丧失或死亡等级，他仍旧会昏迷或死亡。",
