    "keywords": [],
    "description": "本法术可以制造出一个魔法环来驱离不死生物、惧魔或惧魔构装体。魔法师将唾沫吐于他的手中，然后用他的手指画出一个4码半径的圆环，进行一次施法检定（6）。如果成功，圆环会抵抗任何试图进入其中的不死生物、惧魔或惧魔构装体。魔法师进行一次施法检定对抗该实体的秘法防御。\n如果成功，圆环会驱离并对该实体造成伤害。效果检定决定了能对该实体造成的伤害量。\n本法术每轮只能驱离一个实体。如果复数的敌人包围了这个圆环，它们就可以轻松地闯越它。倘若有超过一个实体进入了圆环，圆环就会试图驱离其中拥有最高的秘法防御的实体。若准备时间充足，魔法师可以在生命环中套放多个圆环，制造出同心圆来保护站在正中心的人，并在几分钟内在抵御复数实体时提供一些保护。",
