    "description": "束缚。本法术会将周围空气中的迷雾聚合在一起，施法者可以在施法时将一个邪恶精魂束缚在一名深陷雾中的自愿目标上。魔法师向开放空气中吹气并进行一次施法检定对抗目标的秘法防御。如果成功，目标在法术持续时间内获得近战攻击检定、伤害检定以及物理防御上的+3。在此期间，束缚的精魂会在每轮敦促他们去攻击最近除了精魂与不死生物以外的目标。如果想要抵抗这种冲动，他们可以进行一次意志检定对抗精魂的社交防御（12）。\n倘若他们成功抵御冲动或攻击了任何精魂与不死生物，法术就会结束，束缚的精魂会立即离开（不过它们可能会对冒犯者心怀怨恨），并且本法术与召唤迷雾幽魂（Summon Fog Ghost）不能在一整天之内再次施放。此法术同一时间只能施放激活一次。\n本法术可与召唤迷雾幽魂储存在同一法术矩阵中。",
