    "description": "召唤。本法术将周围空气中的雾气聚合在一起诱使一个邪恶精魂栖身于其中。魔法师向开放空气中吹气并进行一次施法检定对抗精魂的秘法防御（见下），魔法师可以为法术效果选择一个使用一个较低的有效环数。如果成功，迷雾幽魂便会出现在法术范围内魔法师希望的地方，然后它会立刻攻击最近的角色（包括魔法师自己）。每一轮，迷雾幽魂会不加选择地攻击最近的目标，在其攻击与伤害检定中使用效果Step，直至它被消灭或法术结束。\n雾气几乎不会受到物理攻击的影响，但包含精魂的星界范式可以被任何对抗幽魂的秘法防御（下界术士环数+5）或物理防御（下界术士环数+15）的攻击破坏。要成功破坏范式，角色必须在单次攻击中造成大于等于效果Step的伤害。破坏迷雾不会对精魂造成伤害，它只会回到其下界并等待着下一次伤害生者的机会。\n迷雾幽魂不会攻击不死生物或其他精魂。本法术不能在沙漠或其他非常干燥的环境中施放，也不能在温度在冰点以下时施放。此法术同一时间只能施放激活一次（包括迷雾幽魂之貌）。\n本法术可与迷雾幽魂之貌储存在同一法术矩阵中。\n三环",
    "nameCn": "召唤迷雾幽魂",
