    "description": "本法术能召唤出一片会让那些处于雾气萦绕之中的对象产生恐惧的迷雾。魔法师像周围很冷一样环抱双臂，然后指向雾气将出现的地方进行一次施法检定（6）。如果成功，一片明亮而灰蒙蒙的冷雾会在那个位置四周凝聚成一个4码半径的球体。一旦被召唤，雾气就无法移动。魔法师可以以一个简单动作对影响区域内所有目标使用其恫吓天赋，这会让他充满威胁之意的面孔看起来像是用雾气组成的。",
