    "description": "召唤。本法术会从施法等级×10英里范围内的魔法师的一个骸骨之环中召唤骨精魂，使得它能够在圆环外短暂存在一段时间。魔法师拿来两根骨头，一根丢到地上用脚踩在上面，然后挥舞另一根骨头，进行一次施法检定对抗骨精魂的秘法防御。如果成功，骨精魂就会出现在他面前。骨精魂无法离开魔法师超过10码的距离。如果它被迫这么做了，法术将终止，精魂会回到它的骸骨之环。\n骨精魂会服从任何魔法师下达给它的命令——加入战斗、报告在它骸骨之环范围视野内发生的事情等。骨精魂不喜欢离开它们的圆环，所以它们会抵抗频繁的召唤尝试。在一天之内对同一骨精魂每一次额外的召唤尝试都需要一个额外的成功。骨精魂会在法术结束时回到它的圆环。如果精魂在战斗中被摧毁，它的骸骨之环也同样会被毁掉。\n此法术可与骨精魂之貌储存在同一法术矩阵中。\n四环",
    "nameCn": "召唤骨精魂",
    "weavingBase": 7,
    "weavingHigh": 12,
    "castingType": "TMD",
    "castingDn": null,
    "aoe": "",
    "armorType": "none",
    "desc": "召唤。本法术会从施法等级×10英里范围内的魔法师的一个骸骨之环中召唤骨精魂，使得它能够在圆环外短暂存在一段时间。魔法师拿来两根骨头，一根丢到地上用脚踩在上面，然后挥舞另一根骨头，进行一次施法检定对抗骨精魂的秘法防御。如果成功，骨精魂就会出现在他面前。骨精魂无法离开魔法师超过10码的距离。如果它被迫这么做了，法术将终止，精魂会回到它的骸骨之环。\n骨精魂会服从任何魔法师下达给它的命令——加入战斗、报告在它骸骨之环范围视野内发生的事情等。骨精魂不喜欢离开它们的圆环，所以它们会抵抗频繁的召唤尝试。在一天之内对同一骨精魂每一次额外的召唤尝试都需要一个额外的成功。骨精魂会在法术结束时回到它的圆环。如果精魂在战斗中被摧毁，它的骸骨之环也同样会被毁掉。\n此法术可与骨精魂之貌储存在同一法术矩阵中。\n四环"
