    "description": "束缚。本法术可以召唤一只可怖精魂并将其暂时束缚到一个自愿目标身上。魔法师触碰目标并在目标面前跪下，进行一次施法检定对抗目标的秘法防御。如果成功，精魂就会在目标上物质化并与他融合。目标的姿态立即变得僵硬起来，所有的动作都带有一种力量感。他的面孔变得锐利，眼中闪烁着超脱的残酷，暗影紧随在他的身边。\n当此法术激活时，所有GM角色对目标的态度都为中立。目标在基于威吓和恐惧的检定中获得+6。法术结束时，目标对任何之前应用过法术增益的GM角色的态度都会下降一级。\n目标任何直接帮助束缚角色以外的人的行动（例如治疗他们，甚至是打开一扇门）都会导致法术立即结束。如果目标未使用法术给予的增益，或法术提前结束，则该法术在一整天内都无法再次施展，且目标基于意志的检定会承受-3的罚值，直至他们获得一整晚的休息。此法术同一时间只能施放激活一次。\n本法术可以变得非常容易上瘾，因为它所赋予的力量感是一种令人兴奋的冲动。在GM的判断下，精魂可以尝试在持续时间结束后继续束缚于目标身上。要放逐一个不情愿离开的精魂，角色必须在对抗法术驱散难度的意志检定中获得成功。该检定每个持续间隔（等级数分钟）都可以进行一次尝试。",
    "nameCn": "险恶暴君之貌",
    "weavingBase": 8,
    "weavingHigh": 13,
    "castingType": "TMD",
    "castingDn": null,
    "aoe": "",
    "armorType": "none",
    "desc": "束缚。本法术可以召唤一只可怖精魂并将其暂时束缚到一个自愿目标身上。魔法师触碰目标并在目标面前跪下，进行一次施法检定对抗目标的秘法防御。如果成功，精魂就会在目标上物质化并与他融合。目标的姿态立即变得僵硬起来，所有的动作都带有一种力量感。他的面孔变得锐利，眼中闪烁着超脱的残酷，暗影紧随在他的身边。\n当此法术激活时，所有GM角色对目标的态度都为中立。目标在基于威吓和恐惧的检定中获得+6。法术结束时，目标对任何之前应用过法术增益的GM角色的态度都会下降一级。\n目标任何直接帮助束缚角色以外的人的行动（例如治疗他们，甚至是打开一扇门）都会导致法术立即结束。如果目标未使用法术给予的增益，或法术提前结束，则该法术在一整天内都无法再次施展，且目标基于意志的检定会承受-3的罚值，直至他们获得一整晚的休息。此法术同一时间只能施放激活一次。\n本法术可以变得非常容易上瘾，因为它所赋予的力量感是一种令人兴奋的冲动。在GM的判断下，精魂可以尝试在持续时间结束后继续束缚于目标身上。要放逐一个不情愿离开的精魂，角色必须在对抗法术驱散难度的意志检定中获得成功。该检定每个持续间隔（等级数分钟）都可以进行一次尝试。"
