    "description": "本法术能够逆转333页肢体萎缩Wither Limb法术的效果并恢复受伤的肢体。魔法师接触该肢体，将来自另一位面的能量注入进去，然后进行一次施法检定对抗目标的秘法防御。如果成功，肢体就会恢复成正常状态。萎缩的肢体不会立即完全恢复健康。目标使用该肢体进行的任何行动检定仍旧将承受-3的罚值，直到萎缩带来的负伤被治愈。在负伤被治愈之后，肢体就会完全恢复其力量。",
