    "keywords": [],
    "description": "这个可怕的法术会令腿、手臂、翅膀和尾巴萎缩。魔法师指向目标的一根肢体低语\"萎缩\"，接着进行一次施法检定对抗目标的秘法防御。如果成功，其效果检定会决定能够造成的伤害量。若目标承受了1负伤，他的肢体就会随着肌肉萎缩而变得干枯无力。目标在其使用该肢体进行任意行动检定的轮内都被视作陷入烦扰状态。如果一条手臂萎缩，目标就不能用那边的手臂携带超过2磅重的物品，包括武器或盾牌。如果一条腿或一面的翅膀萎缩，相应的移动速率就会减半。如果两条腿或双翅都萎缩了，那么目标则无法使用相应的移动形式，这通常意味着他陷入了击倒状态（无需进行击倒检定），只能以2移动速率爬行。负伤将一直存在，直至肢体得到恢复。只有强大的治愈魔法，例如逆转萎缩Reverse Withering法术，才能完全恢复肢体的使用。\n六环",
