    "description": "本法术可以从星界空间中召唤出一张巨大的嘴。纷飞的谣言表示这会召唤出一个真正的惧魔，这对尤其会使用下界术的魔法师的可怖声誉毫无益处。魔法师发出咀嚼的声音并进行一次施法检定对抗他的秘法防御。如果成功，一张被扭动触手环绕而生有利齿、大到能吞下一个巨魔的巨口就会从下界的深处被唤出。每一轮，这张嘴会攻击一名范围内由魔法师指定的目标，将效果Step用于攻击检定。这需要施法者的专注来维持和引导巨口，若专注被打破，巨口就会消失，法术结束。\n星界咽喉适用于下列特殊规则：\n吞噬：若星界咽喉在攻击检定中获得三个成功，任何巨魔及以下大小的目标都会被整个吞噬。一旦被吞下，效果检定会决定造成的伤害量。受害者可以通过一次成功的力量（12）检定逃离。那些死在了星界咽喉中的人仍旧停留在星界，但可以通过适当法术或天赋恢复。",
    "nameCn": "星界咽喉",
    "weavingBase": 10,
    "weavingHigh": 15,
