    "description": "本法术能让魔法师通过星界从一片阴影移动到另一片阴影。魔法师必须站在一处阴影边，包括他自己的影子，进行一次施法检定对抗他自己的秘法防御。魔法师必须能够看到目的地的影子，但可以使用超出其天生视力的方式做到这一点。\n如果成功，附近的阴影将成为通过星界位面的\"隧道\"另一端临时的\"门户\"。魔法师能在阴影之间移动的最大距离为100码。他以正常的移动速率穿过星界空间，并免受其中的危险。一旦魔法师离开星界空间，法术结束。若魔法师没能在法术结束之前从另一边出去，他就会被困在星界空间。\n被困的魔法师可以通过其他他们可用的方式离开星界位面。影之门也能让星界实体进入物质世界。\n七环",
