    "description": "束缚。本法术可以召唤一只谋杀精魂并将其暂时束缚到一个自愿目标身上。魔法师慢慢舔舐利刃武器的边缘，然后进行一次施法检定对抗目标的秘法防御。如果成功，精魂就会在目标上物质化并与他融合。目标的指甲延伸变长，血从指甲床中渗出。法术的目标会被杀戮的欲望所压倒，并在对措手不及、击倒和惊愕中的敌对方的近战攻击和伤害检定中获得+5。\n若目标有机会攻击一个措手不及、击倒或惊愕中的目标，但没有这么做，法术将立即终止。如果目标在受此法术影响中没有造成任何伤害，或法术因任意原因提早结束。他们都将承受1负伤。如果本法术提早结束或目标由此承受了1负伤，该法术在一整天内都不能被再次施放。此法术同一时间只能施放激活一次。",
