    "description": "本法术会用星界力量压制一名角色的心脏。魔法师伸出手做抓取动作，然后进行一次施法检定对抗目标的秘法防御。如果成功，目标的心脏就会像被钳子钳住一样被压缩。每轮的效果检定会决定造成的伤害量。\n魔法师必须每轮专注才能造成伤害，否则法术将结束。目标被禁足（immobilized），无法采取任何需要移动的行为，除非他进行一次意志检定对抗效果Step。如果成功，法术会结束。有些生物不受此法术影响，因为它们是不死生物、不会感到疼痛，或者没有心脏或类似能被钳制的器官。",
