    "description": "本法术可以诱捕一个不死生物、惧魔、惧魔构装体或物理显现的精魂。魔法师进行一次施法检定对抗目标的秘法防御。如果成功，一圈描有金色文字的耀眼红光会环绕住目标，阻止它的移动。\n如果魔法师想要和这样的生物交谈的话，目标仍旧可以交流。每分钟目标都可以进行一次意志检定对抗效果Step来挣脱法术。如果成功，束缚将被打破，法术结束。任何对该实体的敌对行为都会立刻终止法术。\n八环",
