    "description": "束缚。本法术可以召唤一只疯狂精魂并将其暂时束缚到一个自愿目标身上。魔法师合上目标的眼睛，嘶嘶低语，然后进行一次施法检定对抗目标的秘法防御。如果成功，精魂就会在目标上物质化并与他融合。目标的眼睛变成燃烧着彼世火焰的黑色。本法术的目标将部分融入星界空间并不受任何由星界视觉天赋带来的阻碍影响地去进行侦察。目标获得+4的物理防御和星界视觉检定加值，并在法术持续期间不带来劳累值。\n此外，束缚角色可以通过进行一次对抗秘法防御的星界视觉检定来研究真实范式，以获得关于其功能的额外洞见。如果成功，他每有一成功就会在对目标的所有施法检定和效果Steps中获得+2。他可以选择洞察范式而非获取加值，特别是洞察那些标准的星界视觉无法获得的信息。信息由GM抉择——这是一种疯狂的洞察力。\n每一轮，感知原始星界空间的效果都会对目标产生相当于魔法师用原始魔法施放一个一环法术带来的伤害。此法术同一时间只能施放激活一次。",
    "nameCn": "星界侍从之貌",
    "weavingBase": 12,
    "weavingHigh": 17,
    "castingType": "TMD",
    "castingDn": null,
    "aoe": "",
    "armorType": "none",
    "desc": "束缚。本法术可以召唤一只疯狂精魂并将其暂时束缚到一个自愿目标身上。魔法师合上目标的眼睛，嘶嘶低语，然后进行一次施法检定对抗目标的秘法防御。如果成功，精魂就会在目标上物质化并与他融合。目标的眼睛变成燃烧着彼世火焰的黑色。本法术的目标将部分融入星界空间并不受任何由星界视觉天赋带来的阻碍影响地去进行侦察。目标获得+4的物理防御和星界视觉检定加值，并在法术持续期间不带来劳累值。\n此外，束缚角色可以通过进行一次对抗秘法防御的星界视觉检定来研究真实范式，以获得关于其功能的额外洞见。如果成功，他每有一成功就会在对目标的所有施法检定和效果Steps中获得+2。他可以选择洞察范式而非获取加值，特别是洞察那些标准的星界视觉无法获得的信息。信息由GM抉择——这是一种疯狂的洞察力。\n每一轮，感知原始星界空间的效果都会对目标产生相当于魔法师用原始魔法施放一个一环法术带来的伤害。此法术同一时间只能施放激活一次。"
