    "description": "这个危险的法术会从星界空间中召唤一名惧魔。魔法师必须知道他想要唤出的惧魔的真名，然后小心地刻出半径4码的圆环，将其涂成金色与白色。施法法术会削弱魔法师，其中要用到血魔法，对其造成1点血魔法伤害，施法期间每有一次失败的脉路编织检定就会多造成1点血魔法伤害。\n这些伤害一年零一天内都无法治愈。如果魔法师在完成法术之前解除了它，反弹的魔法将导致他承受Step25的伤害（秘法护甲可用）。\n魔法师触碰圆环，大声呼唤惧魔的真名，然后进行一次施法检定对抗惧魔的秘法防御。如果成功，惧魔将从星界空间召唤至保护环中。惧魔将停留在圆环之中，直至其进行了一次成功的意志检定或驱散魔法检定来对抗法术的驱散难度、被魔法师释放或法术结束。惧魔可以每小时尝试一次意志检定或驱散魔法检定，如果成功，法术结束。\n很多惧魔都会与它们的召唤者协商，为了被释放进物质位面而提供给他们巨大的回报。倘若它们的提议被接受，惧魔通常会兑现承诺，但往往会在日后返回并收回所有宝藏。很少有魔法师会教授此法术——角色应该会疑惑这么做的人的动机，因为惧魔经常把教授呼唤惧魔法术作为其交易的一部分。当法术结束，惧魔会回到星界空间。",
    "nameCn": "呼唤惧魔",
    "weavingBase": 12,
    "weavingHigh": 17,
    "castingType": "TMD",
    "castingDn": null,
    "aoe": "4码半径",
    "armorType": "none",
