    "description": "本法术会让角色慢慢凋零直至死亡。魔法师对目标说出一个可怖的预言，然后触碰目标并进行一次施法检定对抗目标的秘法防御。如果成功，他的效果检定决定了目标每个月会减轻的体重磅数（天生秘法护甲可减轻该效果）。这将持续到法术结束或角色死亡。如果角色的重量下降到了他种族平均体重的百分之五十以下，他就会变得虚弱发昏，在这种情况下视作陷入烦扰状态。如果目标的体重下降到了其种族平均值的百分之二十五以下，除了体重减轻以外，他还会每月承受效果Step的伤害（该伤害在法术结束之前无法被治愈）。",
