    "keywords": [],
    "description": "本法术可以强化星界视觉天赋的使用。魔法师向上转动眼睛，进行一次施法检定对抗其秘法防御。如果成功，他便能够不承受劳累值地使用星界视觉，并且可以感知不在他视线范围内的魔法存在（例如在他身后或隐藏的魔法）。没有星界视觉天赋的角色默认在星界视觉检定中使用感知。魔法师通常会在施法后花费些时间清扫区域并确认感知到的星界存在不是由其同伴构成。魔法师可以尝试对他星界感知到的目标施法，即便他无法通过其他方式看到目标。魔法师可因多个原因而使用本法术，往往是为了简化繁琐的增强星界检测。与星界视觉的正常使用一样，魔法师使用星界感应法术来查看一件脉路物品时能够感知到它的真实范式，并能够得知其魔法本质。不过，他不会获得任何关于该物品的历史信息和关键知识。",
