    "desc": "本法术能够用一段绳子制造出一节梯子。魔法师解开绳子，进行一次施法检定（6）。如果成功，绳子会以移动速率10的速度移动到魔法师在效果区域内所选择的位置。魔法师不能精准控制绳子，比如绳子不能自己系到窗户栏杆上。绳段将直接从A点移动到B点。爬绳的角色在攀爬检定中获得+4加值。这段绳子最多能承受600磅的重量。"
