    "description": "本法术可以鉴别一个人、一个地方或一件物品上的魔法类型。魔法师专注地凝视目标，进行一次施法检定对抗目标的秘法防御。如果成功，成功数将决定魔法师能够得知的信息。一个成功能够揭示目标是否具有魔法；两个成功能够揭示目标所带魔法的大致类型——习艺者才能、先天的魔法、法术魔法等等；三个成功则能够揭示魔法的确切性质，如目标对习艺者而言的门类和环数或对魔法物品而言的能力。使用本法术不会提供任何对脉路物品关键知识的信息，只能知道它是一件脉路物品和对其能力的大致感觉。",
