    "description": "本法术可以让物品或角色在半径2码的无形平台上垂直上浮或下落。魔法师举起又放下他的手，进行一次施法检定对抗效果区域内所有角色或物品中最高的秘法防御。\n如果成功，法术会制造出一个平台，以每轮4码的速度将上面的东西提升或下放，最高可达到法术范围相当的高度。一发法术能支持起1000磅的重量。\n魔法师可以\"叠加\"悬浮术以提升其效果。他可以在已有的平台上再施法一次来增加法术能够承受的重量。魔法师也能在上升至最大高度之后再次施放（多个）悬浮术来将高度提得更高。叠加法术必须要小心处理，一旦任何一个高度较低的悬浮术结束，所有更高的悬浮术都会失效。平台上的角色和物品在法术失效时会根据下落的距离承受坠落伤害（见GM手册）。\n向上移动平台需要魔法师专注，不论他正在操作多少\"叠加\"的法术。若失去专注，平台会以每轮4码的速度自动下降至地面。\n如果平台上的角色或物品数量增加（比如又有一个人跳了上去），魔法师必须再进行一次施法检定。倘若失败，法术结束。",
    "nameCn": "悬浮术",
    "weavingBase": 7,
    "weavingHigh": 12,
    "castingType": "TMD",
    "castingDn": null,
    "aoe": "2码半径",
