    "description": "本法术会在目标的星界范式上放置一枚符号或标记。魔法师进行一次施法检定对抗目标的秘法防御。如果成功，一枚标记会被放置在目标的星界印记上，任何使用星界视觉（如星界视觉天赋，见129页）的人都能看得到它，这可以用来标记目标的犯罪行径或其他不当行为。\n标记也会作为目标和魔法师之间的链接运作。因此，当目标在魔法师的视线范围内时，它能让魔法师对其施法，就像魔法师正在触碰目标一样。印记样式取决于魔法师个人。有传言说这个法术可能是一名惧魔教授给授名者的，所以它的使用常常被质疑。\n四环",
