    "description": "本法术会唤出一个由数缕秘法能量组成的球体。魔法师将一个想象中的结打在一件物品上，标记出原点，然后进行一次施法检定（6）。如果成功，一团魔法线球就会出现在他的手中。球体可以被放置在袋子或口袋里，丝线在魔法师走动时自动释出。魔法师每一小时进行一次效果检定（10）。若检定成功，线球就会放出更多的线并且不会打结。如果失败，线绳就会断裂，法术结束。\n当魔法师想要回到他一开始的地方，他就得把线绕回球上。开始绕线时，丝线会放出白光。通过跟随发光的线绳，魔法师会被准确地带回出发的原点。",
