    "description": "本法术会让小件物品疯狂旋转。魔法师模仿出玩戏法的动作，然后进行一次施法检定对抗效果区域内角色最高的秘法防御。如果成功，所有在效果区域内的小物品都会狂乱地打起转，撞在那些站在同一区域的人身上。效果检定决定了对每一名角色造成的伤害量。\n魔法师可以将法术效果区域移动2码，这需要一次成功的施法检定对抗新的效果区域内角色最高的秘法防御（即便他们先前已经处于效果影响之中）。让物品保持旋转需要魔法师每轮的专注，他唯一能采取而不会终止法术的行动是移动法术效果的施法检定。若效果区域内没有可移动的小物品，法术无效。",
