    "desc": "本法术可以让角色变大。魔法师踮起脚尖或让衣服鼓起，令其身形显得更为庞大，然后进行一次施法检定对抗目标的秘法防御。如果成功，目标立刻长大其正常体型的一半，在只基于力量、体质的检定和伤害检定中获得+4加值，直至法术结束。\n目标的衣物、护甲同样会改变大小，在法术结束时会变回原样。武器和其他装备不会改变。在受限地形（如卫城或隧道中）使用本法术需要小心。"
