    "keywords": [],
    "description": "本仪式法术可以制造出角色和武器之间的一条链接，这使得武器能够在遗失时被召回。在一周的每一日黎明时分，魔法师花费半小时用自己的一滴血在武器上画出一个小图案。他会在一周的结束编织出第一条法术脉路。然后魔法师在接下来的一周每一日黎明时分花费半小时在角色身上也刻画出同样图案的疤痕，将其与武器链接起来。他会在第二周结束时编织最后一条法术脉路。\n当仪式完成后，魔法师进行一次施法检定对抗角色的秘法防御。如果成功，图案会散发出明亮的光线，接着恢复到其正常状态。角色和武器之间将建立起一条交感链接。角色的死亡或武器的被毁将摧毁这条链接，导致疤痕图案和武器的铭文消失得无影无踪。\n角色武器丢失时，他可用进行一次效果检定（用其自身的意志Step）对抗武器的秘法防御。如果成功，只要武器在法术效果范围内，它就会以移动速率6的速度向角色处转移。\n角色无需视线就能回收武器。如果武器需要进行一次属性检定，例如需要从柜子里出来（力量）或需要沿着一处狭窄的窗台滑动（敏捷），角色可以进行一次效果检定来代替属性检定。\n六环",
    "nameCn": "召回武器",
    "weavingBase": 9,
    "weavingHigh": 14,
    "castingType": "TMD",
    "castingDn": null,
    "aoe": "",
    "armorType": "none",
    "desc": "本仪式法术可以制造出角色和武器之间的一条链接，这使得武器能够在遗失时被召回。在一周的每一日黎明时分，魔法师花费半小时用自己的一滴血在武器上画出一个小图案。他会在一周的结束编织出第一条法术脉路。然后魔法师在接下来的一周每一日黎明时分花费半小时在角色身上也刻画出同样图案的疤痕，将其与武器链接起来。他会在第二周结束时编织最后一条法术脉路。\n当仪式完成后，魔法师进行一次施法检定对抗角色的秘法防御。如果成功，图案会散发出明亮的光线，接着恢复到其正常状态。角色和武器之间将建立起一条交感链接。角色的死亡或武器的被毁将摧毁这条链接，导致疤痕图案和武器的铭文消失得无影无踪。\n角色武器丢失时，他可用进行一次效果检定（用其自身的意志Step）对抗武器的秘法防御。如果成功，只要武器在法术效果范围内，它就会以移动速率6的速度向角色处转移。\n角色无需视线就能回收武器。如果武器需要进行一次属性检定，例如需要从柜子里出来（力量）或需要沿着一处狭窄的窗台滑动（敏捷），角色可以进行一次效果检定来代替属性检定。\n六环"
