    "description": "本法术可以让魔法师远离伤害。魔法师疯狂跳动，进行一次施法检定对抗目标的秘法防御。如果成功，他会被赋予一种魔法\"第六感\"，能够侦测到直接或间接针对他的攻击并自动将其从危险前移走。这包含了那些通常会被回避打击作用的攻击，如措手不及或惊愕攻击，但不包括对抗多数法术这种不允许回避打击作用的攻击。\n每当他被攻击，魔法师可以进行一次回避打击检定对抗攻击检定。如果成功，他会朝魔法师选择的方向移动2码。如果这个方向上有任何障碍，他会尽可能地移动一段距离之后停下来。若移动的距离不足以让他躲开攻击，魔法师仍旧会受到影响。",
