    "description": "本法术能让角色暂时获得一个法术矩阵。魔法师指定他当前的一个法术矩阵被借出，然后向目标投掷一个小物品，比如钱币代币之类的东西，然后进行一次施法检定对抗目标的秘法防御。如果成功，目标可以施放与借来的矩阵调谐（attuned to）的法术。\n目标使用他自己的施法和相应脉路编织天赋去施放借来的法术。他必须能够编织出借来的法术任何必要的脉路或已经编织完成脉路，如\"借来\"的强化矩阵（Enhanced Matrix）一样。若目标并不知晓施法天赋或技能，他将用感知检定代替施法检定。法术矩阵被借出时，魔法师不能用它施放或重调谐（reattune）储存于里面的法术。",
