    "description": "本法术可以从法术矩阵中破坏一个随机法术。目标必须拥有一个或更多的法术矩阵，包括矩阵物件（matrix objects）。魔法师眯起眼，进行一次施法检定对抗目标的秘法防御。如果成功，GM随机选择目标的一个法术矩阵。若目标依旧被星界感知到，矩阵中的法术就会显露出来，魔法师可以强制选择一个不同的法术矩阵（魔法师不会知道新选定矩阵中的法术）。\n魔法师根据所选法术矩阵的等级数所决定的驱散难度（见265页驱散魔法）进行一次效果检定。如果成功，矩阵将清空其当前包含的所有法术。如果受影响的矩阵中的一个法术正在施放过程中，目标可以选择中止法术或使用原始魔法完成施法。本法术可以针对任何类型的法术矩阵，不论是标准矩阵（Standard）、强化矩阵（Enhanced）、护甲矩阵（Armor）还是共享矩阵（Shared）或者矩阵物件。被本法术清空的法术矩阵可以被再次调谐以放置新的法术或它原本包含的法术。",
