    "description": "本法术能将一个法术范式置于一件物品中，使法术能够在之后的时机被施放。物品可以是任何东西，不需要特别的附魔。魔法师触碰物品，进行一次施法检定对抗要储存的法术的驱散难度。如果成功，法术会被放进物品中。任何持有该物品的人都可以像使用法术矩阵一样用其自己的施法天赋来施放它。若法术需要脉路，施法者必须知晓相应的脉路编织天赋。物品的持用者必须接触物品才能施放其中储存的法术。\n一旦储存的法术被施放或本法术结束，法术范式就会从物品中消失。\n八环",
