    "description": "本法术可以捕获其他法术。魔法师做出抓取物品的动作，进行一次施法检定对抗目标的秘法防御。如果成功，魔法师进行一次效果检定对抗目标对其直接施放的法术的施法检定结果。若成功，魔法师可以抓住该法术，直至法术结束或魔法师进行一次施法检定，对被捕获法术范围内的可行目标（包含原施法者）施放捕获的法术。重新施法时，被捕获的法术效果使用原本施法者的数值。如果魔法师在其法术捕获结束时正持有法术，该法术的效果会如常影响到他。魔法师不能施放其他法术，直至他重新施放被捕获的法术或其法术捕获结束。",
