    "desc": "本法术会将目标关进魔法囚笼之中。魔法师吹出一声音调走低的口哨，接着发出一声\"哐啷\"声响，进行一次施法检定对抗目标的秘法防御。如果成功，目标周围就会形成一道囚笼，目标必须能装进囚笼内，否则法术自动失效。一旦被唤出，囚笼便无法移动。\n目标无法离开囚笼，因为这只笼子没有门。被困住的目标在包括对笼子本身的施法和脉路编织检定中承受-5罚值。囚笼可被攻击破坏，它被视作拥有10物理护甲、10秘法护甲和40死亡等级的屏障。"
