    "description": "本法术会从一名魔法师的法术矩阵中夺取一个法术并将其置于施法者自己的一个法术矩阵之中。魔法师通常会用夺取的法术来替换掉法术掠夺，但也可以替换他们的矩阵中任意法术。魔法师进行一次施法检定对抗目标魔法师的秘法防御。如果成功，GM随机选择目标的一个法术矩阵。魔法师进行一次效果检定对抗基于法术环数的驱散难度。若成功，该法术会脱离目标法术矩阵并出现在施法者的一个矩阵中。被夺取的法术会一直留在魔法师的法术矩阵中，直至被施放或被替换，取决于该法术。\n若施放夺取法术超出了魔法师的能力范围（没有相应的脉路编织天赋或环数不够），他仍可以从矩阵中施放它，就像从他已经调谐的魔法书（grimoire ）中施放一样（见252页）。不论如何，被夺取的法术一旦被施放就会从他的法术矩阵中消失。如果魔法师能够施放夺取的法术，他可以照常使用它，在这种情况下，法术会被保留在他的法术矩阵中，直至被另一法术替换或因重调谐失败而被抹消。倘若夺取的法术于魔法师而言是未知的，他可以尝试通过辨识范式检定来学习法术（见251页学习法术）。如果成功，他可以花费相应的传说点数来将法术加入他的魔法书。",
